def criticalConnections(V, adj):
    timer = 0
    tin = [-1] * V
    low = [-1] * V
    visited = [False] * V
    result = []

    def dfs(node, parent):
        nonlocal timer
        visited[node] = True
        tin[node] = low[node] = timer
        timer += 1

        for neighbor in adj[node]:
            if neighbor == parent:
                continue
            if visited[neighbor]:
                low[node] = min(low[node], tin[neighbor])
            else:
                dfs(neighbor, node)
                low[node] = min(low[node], low[neighbor])
                if low[neighbor] > tin[node]:
                    edge = sorted((node, neighbor))
                    result.append(edge)

    for i in range(V):
        if not visited[i]:
            dfs(i, -1)

    result.sort()
    return result
